.win98-container {
  width: 30rem;
  margin: 2rem auto;
  font-family: "Tahoma", "Pixelated MS Sans Serif", sans-serif;
  position: relative;
  isolation: isolate;
  --win98-blue: #0a246a;
  --win98-light: #c0c0c0;
  --win98-dark: #808080;
  --win98-white: #ffffff;
  --win98-black: #000000;
}

.win98-window {
  background: var(--win98-light);
  border: 2px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  position: relative;
  z-index: 10;
  transition: all 0.3s ease;
}

.win98-titlebar {
  background: linear-gradient(to right, var(--win98-blue), #0a248a);
  color: white;
  padding: 3px 2px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--win98-dark);
  position: relative;
  z-index: 20;
}

.win98-title {
  font-size: 0.8rem;
  font-weight: bold;
  margin-left: 2px;
  letter-spacing: 0.5px;
}

.win98-controls {
  display: flex;
  gap: 2px;
  margin-right: 2px;
}

.win98-button {
  width: 16px;
  height: 14px;
  background: var(--win98-light);
  border: 1px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: bold;
  cursor: pointer;
  user-select: none;
}

.win98-button:active {
  border-color: var(--win98-dark) var(--win98-white) var(--win98-white)
    var(--win98-dark);
  padding: 1px 0 0 1px;
}

.win98-content {
  padding: 8px;
}

.win98-menu-bar {
  display: flex;
  gap: 15px;
  margin-bottom: 10px;
  padding: 2px 5px;
  background: var(--win98-light);
  border: 1px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
}

.win98-menu-item {
  font-size: 0.8rem;
  cursor: pointer;
  padding: 1px 3px;
}

.win98-menu-item:hover {
  background: var(--win98-blue);
  color: white;
}

.win98-input-frame {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 15px;
}

.win98-input-label {
  font-size: 0.8rem;
  font-weight: bold;
  min-width: 40px;
}

.win98-input {
  flex: 1;
  height: 22px;
  background: white;
  border: 2px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  font-family: "Tahoma", sans-serif;
  font-size: 0.8rem;
  padding: 0 3px;
  outline: none;
}

.win98-input:focus {
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  background: #ffffe0;
}

.win98-status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--win98-dark);
  color: white;
  padding: 2px 5px;
  font-size: 0.7rem;
  border-top: 1px solid var(--win98-white);
  min-height: 18px;
}

.win98-status-indicators {
  display: flex;
  gap: 5px;
}

.win98-indicator {
  background: var(--win98-white);
  color: var(--win98-black);
  padding: 0 3px;
  border: 1px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  font-weight: bold;
}

.win98-resize-handle {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 15px;
  height: 15px;
  background: linear-gradient(
    135deg,
    transparent 0%,
    transparent 50%,
    var(--win98-dark) 50%,
    var(--win98-dark) 60%,
    transparent 60%
  );
  cursor: nw-resize;
}

.secret-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(
    circle at center,
    rgba(0, 255, 255, 0.1) 0%,
    transparent 70%
  );
  opacity: 0;
  transition: all 0.8s ease;
  z-index: 5;
  pointer-events: none;
}

.matrix-rain {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: linear-gradient(
    0deg,
    transparent 0%,
    rgba(0, 255, 0, 0.1) 2%,
    transparent 4%
  );
  background-size: 100% 30px;
  opacity: 0;
  z-index: 6;
  pointer-events: none;
  animation: matrix-fall 2s linear infinite;
}

.glitch-effect {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  z-index: 7;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.hologram-projection {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border: 2px solid rgba(0, 255, 255, 0.5);
  border-radius: 0;
  opacity: 0;
  z-index: 4;
  pointer-events: none;
  box-shadow: 0 0 30px rgba(0, 255, 255, 0.3);
}

.win98-container:hover .win98-window {
