}

.win98-container:focus-within .win98-resize-handle {
  background: linear-gradient(
    135deg,
    transparent 0%,
    transparent 50%,
    #00ffff 50%,
    #00ffff 60%,
    transparent 60%
  );
  box-shadow: 0 0 10px #00ffff;
}

.win98-container:focus-within .secret-overlay {
  opacity: 0.6;
  animation: overlay-pulse 4s ease-in-out infinite;
}

.win98-container:focus-within .matrix-rain {
  opacity: 0.4;
  animation: matrix-fall 0.5s linear infinite;
}

.win98-container:focus-within .glitch-effect {
  opacity: 0.5;
  animation: glitch-subtle 0.3s ease-in-out infinite alternate;
}

.win98-container:focus-within .hologram-projection {
  opacity: 0.7;
  animation: projection-pulse 3s ease-in-out infinite;
}

/* Animations */
@keyframes title-glow {
  0% {
    box-shadow: 0 0 8px rgba(0, 255, 255, 0.4);
  }
  100% {
    box-shadow: 0 0 20px rgba(0, 255, 255, 0.7);
  }
}

@keyframes text-flicker {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.9;
  }
}

@keyframes matrix-fall {
  0% {
    background-position: 0 0;
  }
  100% {
    background-position: 0 30px;
  }
}

@keyframes overlay-pulse {
  0%,
  100% {
    opacity: 0.4;
    transform: scale(1);
  }
  50% {
    opacity: 0.7;
    transform: scale(1.01);
  }
}

@keyframes glitch-subtle {
  0% {
    transform: translate(0);
    opacity: 0.5;
  }
  20% {
    transform: translate(-1px, 1px);
    opacity: 0.7;
  }
  40% {
    transform: translate(1px, -1px);
    opacity: 0.5;
  }
  60% {
    transform: translate(-0.5px, 0.5px);
    opacity: 0.6;
  }
  80% {
    transform: translate(0.5px, -0.5px);
    opacity: 0.7;
  }
  100% {
    transform: translate(0);
    opacity: 0.5;
  }
}

@keyframes projection-pulse {
  0%,
  100% {
    opacity: 0.5;
    box-shadow: 0 0 15px rgba(0, 255, 255, 0.2);
  }
  50% {
    opacity: 0.8;
    box-shadow: 0 0 30px rgba(0, 255, 255, 0.4);
  }
}

/* level settings 👇 */

.slider {
  /* slider */
  --slider-width: 100%;
  --slider-height: 50px;
  --slider-bg: rgb(82, 82, 82);
  --slider-border-radius: 9px;
  /* level */
  --level-color: #fff;
  --level-transition-duration: 0.1s;
  /* icon */
  --icon-margin: 15px;
  --icon-color: var(--slider-bg);
  --icon-size: 25px;
}

.slider {
  position: relative;
  cursor: pointer;
  display: -webkit-inline-box;
  display: -ms-inline-flexbox;
  display: inline-flex;
  -webkit-box-orient: horizontal;
  -webkit-box-direction: reverse;
  -ms-flex-direction: row-reverse;
  flex-direction: row-reverse;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
}

.slider .volume {
  display: inline-block;
  vertical-align: top;
  margin-right: var(--icon-margin);
  color: var(--icon-color);
  width: var(--icon-size);
  height: auto;
  position: absolute;
  left: 0;
  pointer-events: none;
}

.slider .level {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  width: var(--slider-width);
  height: var(--slider-height);
  background: var(--slider-bg);
  overflow: hidden;
  border-radius: var(--slider-border-radius);
  -webkit-transition: height var(--level-transition-duration);
  -o-transition: height var(--level-transition-duration);
  transition: height var(--level-transition-duration);
  cursor: inherit;
  transform: rotate(270deg);
}

.slider .level::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 0;
  height: 0;
  -webkit-box-shadow: -200px 0 0 200px var(--level-color);
  box-shadow: -200px 0 0 200px var(--level-color);
}
.slider .level::-moz-range-thumb {
  width: 0;
  height: 0;
  border-radius: 0;
  border: none;
  box-shadow: -200px 0 0 200px var(--level-color);
}

