.search-container {
  position: relative;
  width: 100%;
  max-width: 380px;
  padding-top: 24px;
  padding-bottom: 22px;
}

.search-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  background: linear-gradient(145deg, #18181a 0%, #0c0c0b 50%, #141413 100%);
  border: 2px solid #2a2820;
  padding: 0;
  box-shadow:
    0 8px 30px rgba(0, 0, 0, 0.6),
    0 0 0 1px rgba(107, 138, 58, 0.08),
    inset 0 2px 6px rgba(0, 0, 0, 0.5);
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
  box-sizing: border-box;
}

.search-wrapper::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    #4a5a2a 15%,
    #8ba859 50%,
    #4a5a2a 85%,
    transparent 100%
  );
  opacity: 0;
  transition: opacity 0.4s ease;
}

.search-wrapper:focus-within::before {
  opacity: 1;
  animation: lineGlow 2s ease-in-out infinite;
}

@keyframes lineGlow {
  0%,
  100% {
    filter: brightness(1);
  }

  50% {
    filter: brightness(1.5);
  }
}

.search-wrapper::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 3px,
    rgba(0, 0, 0, 0.02) 3px,
    rgba(0, 0, 0, 0.02) 6px
  );
  pointer-events: none;
}

.search-wrapper:focus-within {
  border-color: #4a5a2a;
  transform: translateY(-2px);
  box-shadow:
    0 12px 40px rgba(0, 0, 0, 0.7),
    0 0 30px rgba(107, 138, 58, 0.1),
    0 0 0 1px rgba(107, 138, 58, 0.3),
    inset 0 2px 6px rgba(0, 0, 0, 0.5);
}

.search-wrapper:hover {
  border-color: #3a3830;
}

.search-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  position: relative;
  background: linear-gradient(
    135deg,
    rgba(42, 40, 32, 0.3) 0%,
    transparent 100%
  );
}

.search-icon::after {
