}

.search-btn:hover::before {
  left: 100%;
}

.search-btn::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at center,
    rgba(139, 168, 89, 0.2) 0%,
    transparent 70%
  );
