  box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);
  animation: flicker 2s linear infinite;
}

.icon {
  color: rgb(1, 235, 252);
  font-size: 2rem;
  cursor: pointer;
  animation: iconflicker 2s linear infinite;
}

.input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  cursor: pointer !important;
}

@keyframes flicker {
  0% {
    border: 2px solid rgb(1, 235, 252);
    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);
  }

  5% {
    border: none;
    box-shadow: none;
  }

  10% {
    border: 2px solid rgb(1, 235, 252);
    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);
  }

  25% {
    border: none;
    box-shadow: none;
  }

  30% {
    border: 2px solid rgb(1, 235, 252);
    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);
  }

  100% {
    border: 2px solid rgb(1, 235, 252);
    box-shadow: 0px 0px 100px rgb(1, 235, 252) , inset 0px 0px 10px rgb(1, 235, 252),0px 0px 5px rgb(255, 255, 255);
  }
}

@keyframes iconflicker {
  0% {
    opacity: 1;
  }

  5% {
    opacity: 0.2;
  }

  10% {
    opacity: 1;
  }

  25% {
    opacity: 0.2;
  }

  30% {
    opacity: 1;
  }

  100% {
    opacity: 1;
  }
}

.pb-ai-input-wrap {
  position: relative;

  display: flex;
  align-items: center;
  gap: 8px;

  width: fit-content;
  min-width: 290px;
  max-width: 360px;

  padding: 6px;
  border-radius: 999px;

  background: linear-gradient(
    180deg,
    rgba(166, 125, 255, 0.18) 0%,
    rgba(122, 69, 255, 0.12) 100%
  );

  backdrop-filter: blur(14px);

  box-shadow:
    0 0 0 4px rgba(125, 71, 255, 0.08),
    0 0 24px rgba(98, 43, 255, 0.14),
    inset 0 0 6px rgba(255, 255, 255, 0.1);

  overflow: hidden;
  isolation: isolate;
}

/* Gloss */
.pb-ai-input-wrap::before {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: inherit;

  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.16),
    rgba(255, 255, 255, 0.04) 45%,
    rgba(255, 255, 255, 0)
  );

  pointer-events: none;
  z-index: 1;
}

/* Grain */
.pb-ai-input-wrap::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;

  background-image: radial-gradient(
      circle at bottom center,
      rgba(255, 255, 255, 0.18) 0%,
      rgba(255, 255, 255, 0.06) 20%,
      transparent 60%
    ),
    radial-gradient(rgba(255, 255, 255, 0.1) 0.8px, transparent 0.8px);

  background-size:
    100% 100%,
    5px 5px;

  opacity: 0.35;
  mix-blend-mode: overlay;

  pointer-events: none;
  z-index: 2;
}

.pb-ai-input {
  position: relative;
  z-index: 3;

  flex: 1;

  border: none;
  outline: none;
  background: transparent;

  padding: 0 8px;

  color: #ffffff;
  font-size: 13px;
  font-weight: 400;
  letter-spacing: -0.15px;
}

.pb-ai-input::placeholder {
  color: rgba(255, 255, 255, 0.55);
}

.pb-ai-input-btn {
  position: relative;
  z-index: 3;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;

  border: none;
  outline: none;
  cursor: pointer;

  padding: 10px 14px;
  border-radius: 999px;

  color: #fff;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: -0.15px;

  background: linear-gradient(180deg, #a67dff 0%, #7a45ff 45%, #5d24ff 100%);

  box-shadow:
    0 0 0 3px rgba(125, 71, 255, 0.1),
    0 5px 12px rgba(98, 43, 255, 0.2),
    inset 0 2px 8px rgba(255, 255, 255, 0.16);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.pb-ai-input-btn:hover {
  transform: translateY(-1px);

  box-shadow:
    0 0 0 4px rgba(125, 71, 255, 0.12),
    0 8px 16px rgba(98, 43, 255, 0.24),
    inset 0 2px 8px rgba(255, 255, 255, 0.2);
}

.pb-ai-input-btn:active {
  transform: scale(0.97);
}

.pb-ai-sparkle {
  font-size: 12px;
  transform: translateY(-1px);
}

@media (max-width: 640px) {
  .pb-ai-input-wrap {
    width: 100%;
    min-width: unset;
  }

  .pb-ai-input-btn span:first-child {
    display: none;
  }

  .pb-ai-input-btn {
    padding: 10px 12px;
  }
}

